import pytest
from datetime import datetime

@pytest.mark.parametrize(
    "order_id, expected_status",
    [
        (1, 200),  # Valid order ID
        (5, 200),  # Valid order ID
        (10, 200), # Valid order ID
        (6, 404),  # Non-existent order ID
        ("invalid", 400),  # Invalid order ID format (e.g., string instead of integer)
    ]
)
def test_get_order_by_id(api_client, valid_api_key, order_id, expected_status):
    """
    Test fetching order details by order ID.

    - Covers response scenarios: 200, 404, and 400.
    - Validates schema when the response is 200.
    """
    headers = {"Authorization": f"Bearer {valid_api_key}"}
    endpoint = f"store/order/{order_id}"
    response = api_client.get(endpoint, headers=headers)

    assert response.status_code == expected_status

    if response.status_code == 200:
        response_json = response.json()

        # Validate response schema
        assert isinstance(response_json.get("id"), int)
        assert response_json.get("id") == order_id
        assert isinstance(response_json.get("petId"), int)
        assert isinstance(response_json.get("quantity"), int)
        assert isinstance(response_json.get("shipDate"), str)
        assert datetime.fromisoformat(response_json.get("shipDate"))
        assert response_json.get("status") in ["approved", "delivered", "cancelled"]
        assert isinstance(response_json.get("complete"), bool)


